package com.rustypayments.legacy;

import com.rustypayments.PaymentCalendar;
import java.time.*;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;
import java.time.temporal.ChronoUnit;
import java.time.MonthDay;
import java.util.Set;

/**
 * PAYMENT CALENDAR
 * CREATED 03.05.2002
 * CHG 30.08.2008 - cut-off moved from 15:00 to 16:00
 * CHG 09.09.2009 - migrated from the green screens, logic unchanged
 */
public class LegacyPaymentCalendar implements PaymentCalendar {

    private static final ZoneId BANK_ZONE = ZoneId.of("Europe/Warsaw");
    private static final DateTimeFormatter DATE_FMT = DateTimeFormatter.ofPattern("yyyy-MM-dd");

    // Fixed-date holidays for the bank (month‑day)
    private static final Set<MonthDay> BANK_HOLIDAYS = Set.of(
        MonthDay.of(1, 1),   // New Year's Day
        MonthDay.of(1, 6),   // Epiphany (Three Kings)
        MonthDay.of(5, 1),   // Labour Day
        MonthDay.of(5, 3),   // Constitution Day
        MonthDay.of(8, 15),  // Assumption
        MonthDay.of(11, 1),  // All Saints' Day
        MonthDay.of(11, 11), // Independence Day
        MonthDay.of(12, 25), // Christmas
        MonthDay.of(12, 26)  // Boxing Day
    );

    @Override
    public boolean isBusinessDay(String date) {
        if (date == null) {
            throw new IllegalArgumentException("INVALID DATE");
        }
        try {
            LocalDate d = LocalDate.parse(date, DATE_FMT);
            return isBusinessDay(d);
        } catch (DateTimeParseException e) {
            throw new IllegalArgumentException("INVALID DATE: " + date);
        }
    }

    private boolean isBusinessDay(LocalDate date) {
        // Convert to bank zone at start of day
        ZonedDateTime zdt = date.atStartOfDay(BANK_ZONE);
        DayOfWeek dow = zdt.getDayOfWeek();
        if (dow == DayOfWeek.SATURDAY || dow == DayOfWeek.SUNDAY) {
            return false;
        }
        MonthDay md = MonthDay.from(zdt);
        return !BANK_HOLIDAYS.contains(md);
    }

    @Override
    public String processingDate(String submittedAt) {
        if (submittedAt == null) {
            throw new IllegalArgumentException("INVALID TIMESTAMP");
        }
        try {
            OffsetDateTime ot = OffsetDateTime.parse(submittedAt);
            ZonedDateTime zdt = ot.atZoneSameInstant(BANK_ZONE);
            LocalDate date = zdt.toLocalDate();
            if (isBusinessDay(date) && isOnTime(zdt)) {
                return date.format(DATE_FMT);
            }
            return nextBusinessDay(date).format(DATE_FMT);
        } catch (DateTimeParseException e) {
            throw new IllegalArgumentException("INVALID TIMESTAMP: " + submittedAt);
        }
    }

    private boolean isOnTime(ZonedDateTime zdt) {
        int hour = zdt.getHour();
        int minute = zdt.getMinute();
        int second = zdt.getSecond();
        return (hour < 16) || (hour == 16 && minute == 0 && second == 0);
    }

    @Override
    public String settlementDate(String submittedAt) {
        String proc = processingDate(submittedAt);
        LocalDate procDate = LocalDate.parse(proc, DATE_FMT);
        LocalDate settleDate = nextBusinessDay(procDate);
        return settleDate.format(DATE_FMT);
    }

    @Override
    public int daysLate(String dueDate, String paidAt) {
        if (dueDate == null || paidAt == null) {
            throw new IllegalArgumentException("INVALID INPUT");
        }
        try {
            LocalDate due = LocalDate.parse(dueDate, DATE_FMT);
            OffsetDateTime ot = OffsetDateTime.parse(paidAt);
            ZonedDateTime zdt = ot.atZoneSameInstant(BANK_ZONE);
            LocalDate paid = zdt.toLocalDate();
            long days = ChronoUnit.DAYS.between(due, paid);
            return days > 0 ? (int) days : 0;
        } catch (DateTimeParseException e) {
            throw new IllegalArgumentException("INVALID INPUT");
        }
    }

    @Override
    public String addMonths(String date, int months) {
        if (date == null) {
            throw new IllegalArgumentException("INVALID DATE");
        }
        try {
            LocalDate start = LocalDate.parse(date, DATE_FMT);
            YearMonth startYm = YearMonth.from(start);
            YearMonth targetYm = startYm.plusMonths(months);
            boolean isMonthEnd = start.getDayOfMonth() == start.lengthOfMonth();
            LocalDate targetMonthLast = targetYm.atEndOfMonth();
            if (isMonthEnd) {
                return targetMonthLast.format(DATE_FMT);
            } else {
                int day = start.getDayOfMonth();
                int maxDay = targetMonthLast.lengthOfMonth();
                int dayToUse = Math.min(day, maxDay);
                LocalDate result = targetYm.atDay(dayToUse);
                return result.format(DATE_FMT);
            }
        } catch (DateTimeParseException e) {
            throw new IllegalArgumentException("INVALID DATE: " + date);
        }
    }

    private LocalDate nextBusinessDay(LocalDate start) {
        LocalDate cand = start.plusDays(1);
        while (!isBusinessDay(cand)) {
            cand = cand.plusDays(1);
        }
        return cand;
    }

